/** Actual native emitted models, loaded connections, padded item and real Survival interaction packets. */
@EventBusSubscriber(modid="vandorlabs",value=Dist.CLIENT)
public final class TablePlayerChecks {
    private static int stage,ticks,checks,started;private static boolean models;private static String shot;private static int firstWindow;
    private static void need(boolean value,String why){checks++;if(!value)throw new AssertionError("Table client stage="+stage+" ticks="+ticks+": "+why);}
    private static boolean ack(Minecraft mc,int operation){return mc.level.getBlockState(TablePlayerFixture.ACK.east(operation)).is(Blocks.STONE);}
    private static void mode(int operation){PacketDistributor.sendToServer(new TablePlayerFixture.Mode(operation));}
    private static void use(Minecraft mc,BlockPos pos,Direction face){mc.gameMode.useItemOn(mc.player,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(pos).add(Vec3.atLowerCornerOf(face.getNormal()).scale(.5)),face,pos,false));}
    private static List<BakedQuad> quads(net.minecraft.client.resources.model.BakedModel model,BlockState state,ModelData data){var result=new ArrayList<BakedQuad>();for(var face:new Direction[]{null,Direction.DOWN,Direction.UP,Direction.NORTH,Direction.SOUTH,Direction.WEST,Direction.EAST})result.addAll(model.getQuads(state,face,RandomSource.create(0),data,null));return result;}
    private static int installedQuads(Minecraft mc,BlockPos pos){var state=mc.level.getBlockState(pos);var model=mc.getBlockRenderer().getBlockModel(state);return quads(model,state,model.getModelData(mc.level,pos,state,ModelData.EMPTY)).size();}
    private static void models(Minecraft mc){need(System.getProperty("vandorlabs.industrialTable")==null&&System.getProperty("vandorlabs.pressurePlate")==null&&TableBindings.enabled()&&com.vandorlabs.neoforge.plate.NativePlateBindings.enabled(),"ordinary native registration without enable flags");net.minecraft.world.item.CreativeModeTabs.tryRebuildTabContents(mc.level.enabledFeatures(),false,mc.level.registryAccess());var tab=net.minecraft.core.registries.BuiltInRegistries.CREATIVE_MODE_TAB.get(net.minecraft.resources.ResourceLocation.parse("vandorlabs:vandorlabs"));for(var item:new net.minecraft.world.item.Item[]{TableBindings.ITEM,com.vandorlabs.neoforge.plate.NativePlateBindings.ITEM}){need(tab.getDisplayItems().stream().filter(stack->stack.is(item)).count()==1,"one ordinary native creative entry");need(net.minecraft.world.item.CreativeModeTabs.searchTab().getDisplayItems().stream().filter(stack->stack.is(item)).count()==1,"one ordinary native search entry");}int cases=0;for(var face:Direction.Plane.HORIZONTAL)for(boolean inverted:new boolean[]{false,true})for(int mask=0;mask<4;mask++){var state=TableBindings.BLOCK.defaultBlockState().setValue(TableBlock.FACING,face).setValue(TableBlock.UPSIDE_DOWN,inverted).setValue(TableBlock.LEFT,(mask&1)!=0).setValue(TableBlock.RIGHT,(mask&2)!=0);var quads=quads(mc.getBlockRenderer().getBlockModel(state),state,ModelData.EMPTY);need(quads.size()==24-6*Integer.bitCount(mask),"authored table strut count "+state);for(var quad:quads){need(quad.getSprite().contents().name().toString().equals("vandorlabs:block/industrial_table"),"canonical authored material");int[] raw=quad.getVertices();for(int i=0;i<4;i++)for(int axis=0;axis<3;axis++)need(Float.isFinite(Float.intBitsToFloat(raw[i*(raw.length/4)+axis])),"finite emitted vertex");}cases++;}need(cases==32,"all emitted states");var item=new net.minecraft.world.item.ItemStack(TableBindings.ITEM);var model=mc.getItemRenderer().getModel(item,mc.level,mc.player,0);need(quads(model,null,ModelData.EMPTY).size()==24,"standalone padded authored item");need(item.getHoverName().getString().equals("Industrial Table"),"canonical translated name");padding(mc,item);System.out.println("[vandorlabs][table-player] emitted PASS32 authoredStates/variantStruts/materials/standaloneItem");}
    @SubscribeEvent public static void tick(ClientTickEvent.Post event){if(!TablePlayerFixture.enabled())return;var mc=Minecraft.getInstance();if(mc.screen instanceof net.minecraft.client.gui.screens.AccessibilityOnboardingScreen intro){intro.onClose();return;}if(stage==31&&mc.level==null){System.out.println("[vandorlabs][table-player] client PASS checks="+checks+" emittedTable32/realSurvival/pair/inverted/mining/strutRefresh/plate32/previous/material/transmission/copierUndo/ordinaryAndConfigurator");stage=32;mc.stop();return;}if(mc.level==null||mc.player==null||mc.gameMode==null)return;need(++ticks<1200,"timeout mode="+mc.gameMode.getPlayerMode()+" held="+mc.player.getMainHandItem()+" pos="+mc.player.position());mc.getToasts().clear();mc.gui.getChat().clearMessages(true);if(!models){models(mc);models=true;}
        var held=mc.player.getMainHandItem();switch(stage){
            case 0->{if(mc.gameMode.getPlayerMode()!=GameType.SURVIVAL||mc.player.getInventory().selected!=0||!held.is(TableBindings.ITEM)||held.getCount()!=3||mc.player.position().distanceToSqr(.5,96,-3)>.01)return;use(mc,TablePlayerFixture.POS.below(),Direction.UP);stage=1;}
            case 1->{if(!mc.level.getBlockState(TablePlayerFixture.POS).is(TableBindings.BLOCK)||held.getCount()!=2)return;use(mc,TablePlayerFixture.POS.east().below(),Direction.UP);stage=2;}
            case 2->{if(!mc.level.getBlockState(TablePlayerFixture.POS.east()).is(TableBindings.BLOCK)||held.getCount()!=1)return;need(installedQuads(mc,TablePlayerFixture.POS)==18&&installedQuads(mc,TablePlayerFixture.POS.east())==18,"actual region data hides internal struts");mode(0);stage=3;}
            case 3->{if(!ack(mc,0)||mc.player.position().distanceToSqr(1.5,96,-2)>.01)return;use(mc,TablePlayerFixture.CEILING,Direction.DOWN);stage=4;}
            case 4->{if(!held.isEmpty()||!mc.level.getBlockState(TablePlayerFixture.CEILING.below()).is(TableBindings.BLOCK))return;need(mc.level.getBlockState(TablePlayerFixture.CEILING.below()).getValue(TableBlock.UPSIDE_DOWN),"inverted publication");mode(1);stage=5;}
            case 5->{if(!ack(mc,1)||!held.is(net.minecraft.world.item.Items.DIAMOND_PICKAXE))return;var aim=Vec3.atCenterOf(TablePlayerFixture.POS);var delta=aim.subtract(mc.player.getEyePosition());mc.player.setYRot((float)Math.toDegrees(Math.atan2(delta.z,delta.x))-90);mc.player.setXRot((float)-Math.toDegrees(Math.atan2(delta.y,Math.hypot(delta.x,delta.z))));shot="pair";started=ticks;stage=6;}
            case 6->{if(shot!=null||ticks-started<8)return;mc.gameMode.startDestroyBlock(TablePlayerFixture.POS.east(),Direction.NORTH);stage=7;}
            case 7->{if(mc.level.getBlockState(TablePlayerFixture.POS.east()).isAir()){mc.gameMode.stopDestroyBlock();mode(2);stage=8;return;}mc.gameMode.continueDestroyBlock(TablePlayerFixture.POS.east(),Direction.NORTH);}
            case 8->{if(!ack(mc,2)||!mc.levelRenderer.isSectionCompiled(TablePlayerFixture.POS))return;need(installedQuads(mc,TablePlayerFixture.POS)==24,"actual client renderer restores missing end strut");shot="mined";stage=9;}
            case 9->{if(shot!=null)return;mode(3);stage=10;}
            case 10->{if(!ack(mc,3)||!held.is(com.vandorlabs.neoforge.plate.NativePlateBindings.ITEM)||held.getCount()!=1||mc.player.position().distanceToSqr(.5,96,4.5)>.01)return;use(mc,TablePlayerFixture.PLATE.below(),Direction.UP);stage=12;}
            case 12->{if(!held.isEmpty()||!mc.level.getBlockState(TablePlayerFixture.PLATE).is(com.vandorlabs.neoforge.plate.NativePlateBindings.BLOCK))return;mode(4);stage=13;}
            case 13->{if(!ack(mc,4)||!held.is(com.vandorlabs.neoforge.VandorLabsBootstrap.CONFIGURIZER.get()))return;use(mc,TablePlayerFixture.PLATE,Direction.UP);stage=14;}
            case 14->{var screen=plateScreen(mc);if(screen==null)return;need(screen.getMenu().tile.getBlockPos().equals(TablePlayerFixture.PLATE),"dedicated exact plate owner");firstWindow=screen.getMenu().containerId;mode(5);stage=15;}
            case 15->{var screen=plateScreen(mc);if(!ack(mc,5)||screen==null)return;plateModels(mc);click(screen,1,1);stage=16;}
            case 16->{var screen=plateScreen(mc);if(screen==null||screen.getMenu().tile.mode()!=0)return;click(screen,1,0);stage=17;}
            case 17->{var screen=plateScreen(mc);if(screen==null||screen.getMenu().tile.mode()!=1)return;click(screen,2,1);stage=18;}
            case 18->{var screen=plateScreen(mc);if(screen==null||screen.getMenu().tile.sensitivity()!=2)return;int choice=TablePlayerFixture.trapdoorChoice();var picker=screen.picker();picker.searchField().setValue(com.vandorlabs.neoforge.ModernFinishCatalog.option(choice).label());picker.select(choice,true);int index=picker.rows().indexOf(choice)-picker.scroll();need(index>=0&&index<picker.visible(),"actual trapdoor row visible through standard search/scroll");need(screen.mouseClicked(screen.panelLeft()+20,picker.top()+index*22+10,0),"actual material picker click");stage=19;}
            case 19->{var screen=plateScreen(mc);if(screen==null||screen.getMenu().tile.texture()!=TablePlayerFixture.trapdoorChoice())return;need(screen.mouseClicked(screen.panelLeft()+screen.getXSize()-30,screen.getGuiTop()+40,0),"Redstone tab");var transmission=screen.transmissionWidget();transmission.channelField().setValue("65432");transmission.channelField().setFocused(true);need(screen.keyPressed(257,0,0),"inline channels Enter commit");stage=20;}
            case 20->{var screen=plateScreen(mc);if(screen==null||!screen.getMenu().tile.getRedstoneChannels().equals(com.vandorlabs.redstone.ChannelList.of(65432))||screen.getMenu().tile.output()!=1)return;mode(6);stage=21;}
            case 21->{if(!ack(mc,6))return;shot="plate-options";stage=22;}
            case 22->{if(shot!=null)return;mc.player.closeContainer();mode(7);stage=23;}
            case 23->{if(!ack(mc,7)||!held.isEmpty()||mc.screen!=null)return;mc.player.setShiftKeyDown(true);mc.player.connection.send(new net.minecraft.network.protocol.game.ServerboundPlayerCommandPacket(mc.player,net.minecraft.network.protocol.game.ServerboundPlayerCommandPacket.Action.PRESS_SHIFT_KEY));started=ticks;stage=24;}
            case 24->{if(ticks-started<3)return;use(mc,TablePlayerFixture.PLATE,Direction.UP);stage=25;}
            case 25->{var screen=plateScreen(mc);if(screen==null)return;need(screen.getMenu().containerId!=firstWindow&&screen.getMenu().tile.getBlockPos().equals(TablePlayerFixture.PLATE),"ordinary Survival route uses same dedicated owner/controls");mode(8);stage=26;}
            case 26->{if(!ack(mc,8))return;mc.player.setShiftKeyDown(false);mc.player.connection.send(new net.minecraft.network.protocol.game.ServerboundPlayerCommandPacket(mc.player,net.minecraft.network.protocol.game.ServerboundPlayerCommandPacket.Action.RELEASE_SHIFT_KEY));mc.level.disconnect();mc.disconnect();stage=31;}
            default->{}
        }
    }
    private static com.vandorlabs.neoforge.plate.client.NativePlateScreen plateScreen(Minecraft mc){return mc.screen instanceof com.vandorlabs.neoforge.plate.client.NativePlateScreen screen?screen:null;}
    private static void click(com.vandorlabs.neoforge.plate.client.NativePlateScreen screen,int id,int button){var control=screen.option(id);need(control!=null&&screen.mouseClicked(control.getX()+control.getWidth()/2D,control.getY()+8,button),"actual previous/next plate option "+id);}
    private static void plateModels(Minecraft mc){for(int power=0;power<16;power++)for(int material:new int[]{com.vandorlabs.neoforge.plate.NativePlateEntity.DEFAULT_TEXTURE,TablePlayerFixture.trapdoorChoice()}){var state=com.vandorlabs.neoforge.plate.NativePlateBindings.BLOCK.defaultBlockState().setValue(com.vandorlabs.neoforge.plate.NativePlateBlock.POWER,power);var data=ModelData.builder().with(com.vandorlabs.neoforge.plate.NativePlateEntity.TEXTURE,material).build();var faces=quads(mc.getBlockRenderer().getBlockModel(state),state,data);need(faces.size()==6,"six actual thin plate faces");for(var quad:faces){need(quad.getSprite().contents().name().toString().equals(com.vandorlabs.neoforge.ModernFinishCatalog.option(material).texture()),"selected main/trapdoor reaches actual native quad");var raw=quad.getVertices();for(int i=0;i<4;i++){int at=i*(raw.length/4);double x=Float.intBitsToFloat(raw[at]),y=Float.intBitsToFloat(raw[at+1]),z=Float.intBitsToFloat(raw[at+2]);need(x>=1D/16-1e-6&&x<=15D/16+1e-6&&z>=1D/16-1e-6&&z<=15D/16+1e-6&&y>=-1e-6&&y<=(power==0?1:.5)/16D+1e-6,"native thin up/down travel");}}}var icon=new net.minecraft.world.item.ItemStack(com.vandorlabs.neoforge.plate.NativePlateBindings.ITEM);padding(mc,icon);System.out.println("[vandorlabs][table-player] plate-emitted PASS32 main/trapdoor/16analog/thinTravel");}
    private static void padding(Minecraft mc,net.minecraft.world.item.ItemStack stack){var model=mc.getItemRenderer().getModel(stack,mc.level,mc.player,0);var gui=model.getTransforms().gui;int vertices=0;for(var quad:quads(model,null,ModelData.EMPTY)){int[] raw=quad.getVertices();for(int i=0;i<4;i++){int at=i*(raw.length/4);double x=(Float.intBitsToFloat(raw[at])-.5)*gui.scale.x(),y=(Float.intBitsToFloat(raw[at+1])-.5)*gui.scale.y(),z=(Float.intBitsToFloat(raw[at+2])-.5)*gui.scale.z(),rz=Math.toRadians(gui.rotation.z()),ry=Math.toRadians(gui.rotation.y()),rx=Math.toRadians(gui.rotation.x()),a=x*Math.cos(rz)-y*Math.sin(rz);y=x*Math.sin(rz)+y*Math.cos(rz);x=a;a=x*Math.cos(ry)+z*Math.sin(ry);z=z*Math.cos(ry)-x*Math.sin(ry);x=a;y=y*Math.cos(rx)-z*Math.sin(rx);x+=gui.translation.x();y+=gui.translation.y();need(Math.abs(x)<.47&&Math.abs(y)<.47,"item GUI retains visible padding "+stack);vertices++;}}need(vertices>=24,"visible authored item vertices");}
    @SubscribeEvent public static void capture(RenderFrameEvent.Post event)throws Exception{if(!TablePlayerFixture.enabled()||shot==null)return;var mc=Minecraft.getInstance();if(mc.level==null||mc.getOverlay()!=null)return;try(var image=net.minecraft.client.Screenshot.takeScreenshot(mc.getMainRenderTarget())){var path=mc.gameDirectory.toPath().resolve("screenshots/native-table-"+shot+".png");java.nio.file.Files.createDirectories(path.getParent());image.writeToFile(path);}shot=null;}
    private TablePlayerChecks(){}
}
